<?php
namespace Database\Seeders;use App\Models\Category;use App\Models\IncomeSource;use App\Models\PaymentMethod;use App\Models\User;use Illuminate\Database\Seeder;
class DatabaseSeeder extends Seeder{public function run():void{$u=User::factory()->create(['name'=>'Test User','email'=>'test@example.com']);foreach(['Food','Transport','Shopping','Bills','Utilities','Entertainment','Education','Health','Fuel','Rent','Savings','Investment','Miscellaneous'] as $n)Category::create(['user_id'=>$u->id,'name'=>$n,'is_default'=>true]);foreach(['Cash','Mobile Money','Debit Card','Credit Card','Bank Transfer','Other'] as $n)PaymentMethod::create(['user_id'=>$u->id,'name'=>$n]);foreach(['Salary','Business','Freelance','Investment','Gift','Bonus','Scholarship','Other'] as $n)IncomeSource::create(['user_id'=>$u->id,'name'=>$n,'is_default'=>true]);}}
